const body = $json.body || $json;
const sessionId = body.sessionId || `academ_${Date.now()}_${Math.random().toString(36).substr(2,8)}`;
const action = body.action || 'chat';
const mode = body.mode || 'drafting';
const discipline = body.discipline || 'paud';
const outputFormat = body.outputFormat || 'markdown';
const citationFormat = body.citationFormat || 'APA7';
const language = body.language || 'indonesia';

return {
  sessionId, action, mode, discipline,
  outputFormat, citationFormat, language,
  userMessage: body.message || body.query || '',
  targetSection: body.section || null,
  researchTopic: body.topic || null,
  journalCount: body.options?.journalCount || 10,
  yearFilter: body.options?.yearFilter || '2019-2025',
  runCitationValidator: body.options?.runCitationValidator !== false,
  hasUploadedData: body.hasUploadedData || false,
  timestamp: new Date().toISOString()
};

const mode = $json.mode || 'drafting';
const discipline = $json.discipline || 'paud';
const language = $json.language || 'indonesia';
const citationFormat = $json.citationFormat || 'APA7';

const modePrompts = {
  drafting: `Tulis konten ilmiah akademik yang lengkap, pedagogis, dan terstruktur. Gunakan tool Semantic Scholar untuk referensi jurnal ilmiah pendidikan. Sertakan sitasi (Nama, Tahun) pada setiap klaim teori perkembangan anak atau data lapangan. Format Markdown rapi.`,
  editing: `Review dan perbaiki draft skripsi/karya ilmiah. Periksa kejelasan logika pedagogis, terminologi perkembangan anak (kognitif, motorik halus/kasar, afektif, sosio-emosional), konsistensi sitasi, dan bahasa baku sesuai PUEBI/EYD V.`,
  paraphrasing: `Parafrase teks akademik teori/jurnal tanpa mengubah esensi ilmiahnya untuk menghindari plagiarisme/Turnitin. Pertahankan sitasi primer.`,
  SLR: `Lakukan Systematic Literature Review (SLR) pada topik PAUD/pendidikan terkait. Cari 10-15 jurnal di Semantic Scholar. Buat tabel matrik penelitian terdahulu (Peneliti, Tahun, Variabel/Fokus, Metode/Sampel Anak Usia Dini, Hasil Utama, Research Gap).`,
  proposal: `Rancang proposal skripsi lengkap: Judul Penelitian, BAB I (Latar Belakang masalah di TK/PAUD, Rumusan Masalah, Tujuan, Manfaat), BAB II (Kajian Teori: teori perkembangan anak/media pembelajaran APE, Kerangka Berpikir, Hipotesis Tindakan/Asumsi), BAB III (Metodologi Penelitian: PTK / Kuantitatif / Kualitatif Deskriptif, Subjek Anak Didik, Instrumen Observasi).`,
  abstract: `Buat Abstrak bilingual (Indonesia & Inggris) 150-200 kata mencakup: Latar belakang singkat di satuan PAUD, Tujuan, Metode & Instrumen pengamatan, Temuan kunci perkembangan anak, dan Kesimpulan/Implikasi pedagogis. 3-5 Kata Kunci.`,
  statistics: `Interpretasikan hasil pengolahan data penelitian pendidikan (misal: uji efektivitas media APE, uji-t, N-Gain, lembar observasi persentase ketercapaian aspek perkembangan anak). Jelaskan implikasi praktis bagi guru/pendidik anak usia dini.`
};

const modeTemp = {
  drafting: 0.3, editing: 0.2, paraphrasing: 0.6,
  SLR: 0.2, proposal: 0.3, abstract: 0.3, statistics: 0.2
};

return {
  ...$json,
  modePrompt: modePrompts[mode] || modePrompts.drafting,
  temperature: modeTemp[mode] || 0.3,
  modeLabel: mode.toUpperCase()
};

const topic = $json.researchTopic || $json.userMessage;
const journalCount = $json.journalCount || 10;
const yearFilter = $json.yearFilter || '2019-2025';

const sections = [
  { id: 'research_phase', label: '🔍 Research & Journal Mining', mode: 'drafting',
    prompt: `Cari ${journalCount} jurnal peer-reviewed relevan tentang: "${topic}" dari Semantic Scholar (${yearFilter}). Utamakan jurnal pendidikan/anak usia dini. Rangkum teori kunci untuk dipakai di seluruh bab.` },
  { id: 'abstrak', label: '📄 Abstrak (Bilingual)', mode: 'abstract',
    prompt: `Buat draf abstrak Indonesia & Inggris lengkap dengan kata kunci untuk penelitian: "${topic}".` },
  { id: 'bab1', label: '📖 BAB I — Pendahuluan', mode: 'drafting',
    prompt: `Tulis BAB I Pendahuluan lengkap untuk: "${topic}". Sertakan 1.1 Latar Belakang (kondisi ideal vs realitas di lapangan PAUD, data empiris), 1.2 Identifikasi & Pembatasan Masalah, 1.3 Rumusan Masalah, 1.4 Tujuan, 1.5 Manfaat bagi Pendidik, Anak, & Sekolah.` },
  { id: 'bab2', label: '📚 BAB II — Kajian Pustaka', mode: 'SLR',
    prompt: `Tulis BAB II Kajian Teori untuk: "${topic}". Bahas teori perkembangan anak yang relevan (Piaget, Vygotsky, dsb), variabel media/stimulasi, penelitian terdahulu (tabel sintesis), kerangka berpikir, dan hipotesis.` },
  { id: 'bab3', label: '⚙️ BAB III — Metode Penelitian', mode: 'drafting',
    prompt: `Tulis BAB III Metode Penelitian untuk: "${topic}". Tentukan jenis metode (PTK/Kualitatif/Eksperimen), subjek anak didik usia 4-6 tahun, teknik observasi/dokumentasi, kisi-kisi instrumen, dan teknik analisis data.` },
  { id: 'bab4', label: '📊 BAB IV — Hasil & Pembahasan', mode: 'drafting',
    prompt: `Tulis BAB IV Hasil Penelitian dan Pembahasan untuk: "${topic}". Sajikan deskripsi data perkembangan anak, siklus/analisis, komparasi dengan penelitian terdahulu, dan refleksi pedagogis.` },
  { id: 'bab5', label: '🏁 BAB V — Kesimpulan & Saran', mode: 'drafting',
    prompt: `Tulis BAB V Kesimpulan dan Saran rekomendasi praktis bagi guru PAUD, orang tua, dan pengambil kebijakan kurikulum.` },
  { id: 'daftar_pustaka', label: '📑 Daftar Pustaka (APA 7th)', mode: 'drafting',
    prompt: `Susun Daftar Pustaka format APA 7th Edition alfabetis lengkap dari semua referensi yang disitasi.` }
];

return {
  ...$json,
  sections,
  totalSections: sections.length,
  currentIndex: 0,
  completedSections: [],
  startedAt: new Date().toISOString()
};

const content = $json.content || $json.userMessage || '';
const API_BASE = 'https://api.semanticscholar.org/graph/v1';
const API_KEY = $env.SEMANTIC_SCHOLAR_API_KEY || '';
const headers = API_KEY ? { 'x-api-key': API_KEY } : {};

const apaPattern = /\(([A-Z][a-zA-Z\u00C0-\u024F]+(?:(?:\s+&\s+|\s+et\s+al\.)?(?:\s*[A-Z][a-zA-Z]+)*)?),?\s*(\d{4})\)/g;
const doiPattern = /(?:https?:\/\/doi\.org\/|doi:\s*)(10\.\d{4,}\/\S+)/gi;

const citations = [];
let m;

while ((m = apaPattern.exec(content)) !== null) {
  citations.push({ type: 'APA', author: m[1].trim(), year: m[2], raw: m[0] });
}
while ((m = doiPattern.exec(content)) !== null) {
  citations.push({ type: 'DOI', doi: m[1], raw: m[0] });
}

if (citations.length === 0) {
  return { validationReport: '⚠️ Tidak ditemukan sitasi dalam format APA atau DOI pada teks.', summary: { total: 0, valid: 0, partial: 0, invalid: 0 }, allValid: true };
}

const results = [];
for (const cite of citations.slice(0, 15)) {
  let status = 'UNKNOWN';
  let found = null;
  let suggestion = null;
  try {
    if (cite.type === 'DOI') {
      const r = await fetch(`${API_BASE}/paper/DOI:${cite.doi}?fields=title,authors,year,journal`, { headers });
      if (r.ok) { found = await r.json(); status = 'VALID'; }
      else { status = 'INVALID'; suggestion = 'DOI tidak terdaftar.'; }
    } else {
      const q = encodeURIComponent(`${cite.author} ${cite.year}`);
      const r = await fetch(`${API_BASE}/paper/search?query=${q}&fields=title,authors,year,journal&limit=3`, { headers });
      if (r.ok) {
        const data = await r.json();
        const papers = data.data || [];
        const yearMatch = papers.filter(p => String(p.year) === String(cite.year));
        if (yearMatch.length > 0) { found = yearMatch[0]; status = 'VALID'; }
        else if (papers.length > 0) { found = papers[0]; status = 'PARTIAL'; suggestion = `Tahun berbeda: tercatat ${papers[0].year}.`; }
        else { status = 'INVALID'; suggestion = 'Tidak ditemukan di database Semantic Scholar.'; }
      }
    }
  } catch(e) { status = 'ERROR'; suggestion = e.message; }
  results.push({ raw: cite.raw, type: cite.type, status, foundTitle: found?.title, foundYear: found?.year, foundJournal: found?.journal?.name, suggestion });
}

const icons = { VALID:'✅', PARTIAL:'⚠️', INVALID:'❌', ERROR:'🔴', UNKNOWN:'❓' };
const report = results.map(r => {
  let line = `${icons[r.status]} ${r.raw} → ${r.status}`;
  if (r.foundTitle) line += `\n   📄 "${r.foundTitle}" (${r.foundYear}) — ${r.foundJournal || 'Jurnal Terindeks'}`;
  if (r.suggestion) line += `\n   💡 Catatan: ${r.suggestion}`;
  return line;
}).join('\n\n');

const valid = results.filter(r=>r.status==='VALID').length;
const partial = results.filter(r=>r.status==='PARTIAL').length;
const invalid = results.filter(r=>r.status==='INVALID').length;

return {
  validationReport: `📋 LAPORAN VALIDASI SITASI AKADEMIK\n${'='.repeat(45)}\n${report}\n\n📊 Total: ${results.length} sitasi | ✅ ${valid} valid | ⚠️ ${partial} perlu koreksi | ❌ ${invalid} tidak ditemukan`,
  summary: { total: results.length, valid, partial, invalid },
  allValid: invalid === 0
};

const query = $fromAI('query', 'Search query in English');
const limit = $fromAI('limit', 'Number of results (default 10, max 20)', 'number') || 10;
const yearFilter = $fromAI('year_filter', 'Year filter like 2019-2025', 'string') || '';
const API_KEY = $env.SEMANTIC_SCHOLAR_API_KEY || '';
const headers = API_KEY ? { 'x-api-key': API_KEY } : {};
const fields = 'title,authors,year,abstract,citationCount,externalIds,journal,fieldsOfStudy';
let url = `https://api.semanticscholar.org/graph/v1/paper/search?query=${encodeURIComponent(query)}&fields=${fields}&limit=${Math.min(limit, 20)}`;
if (yearFilter) url += `&year=${yearFilter}`;
try {
  const r = await fetch(url, { headers });
  if (!r.ok) return `Error: ${r.status} ${r.statusText}`;
  const data = await r.json();
  if (!data.data?.length) return `Tidak ditemukan paper untuk: "${query}".`;
  const papers = data.data.map((p, i) => {
    const authors = p.authors?.slice(0,3).map(a=>a.name).join(', ') + (p.authors?.length>3?' et al.':'');
    const doi = p.externalIds?.DOI;
    const abstract = p.abstract?.substring(0,350) || 'Abstrak tidak tersedia';
    const apa = doi ? `${authors} (${p.year}). ${p.title}. *${p.journal?.name||''}*. https://doi.org/${doi}` : `${authors} (${p.year}). ${p.title}. *${p.journal?.name||''}*.`;
    return `[${i+1}] **${p.title}**\n    Penulis: ${authors} (${p.year})\n    Jurnal: ${p.journal?.name||'N/A'}\n    Sitasi: ${p.citationCount||0}x | DOI: ${doi?`https://doi.org/${doi}`:'N/A'}\n    Abstrak: ${abstract}...\n    📌 Format APA: ${apa}`;
  }).join('\n\n');
  return `Ditemukan ${data.data.length} paper untuk "${query}":\n\n${papers}`;
} catch(e) { return `Error: ${e.message}`; }

const output = $json.output || $json.text || '';
const req = $('📋 Parse & Validate Request').item.json;
const date = new Date().toLocaleDateString('id-ID', { year:'numeric', month:'long', day:'numeric' });
const header = `---
Project: AcademAI (Built with Gemma 2 Open-Weight AI)
Fokus: Pendidikan Anak Usia Dini (PAUD) & Ilmu Pendidikan
Mode: ${req.mode?.toUpperCase() || 'DRAFTING'}
Session: ${req.sessionId}
Sitasi: ${req.citationFormat} | Tanggal: ${date}
---

`;
const footer = `

---
> 🧸 **AcademAI EduFriend Note**: Selalu konsultasikan hasil draf ini dengan dosen pembimbing skripsi Anda. Data observasi anak didik tetap 100% aman dan terjaga secara lokal.`;
return { documentMarkdown: header + output + footer, wordCount: output.split(/\s+/).length, sessionId: req.sessionId, outputFormat: req.outputFormat, mode: req.mode, timestamp: new Date().toISOString() };

const doc = $json;
return {
  success: true,
  sessionId: doc.sessionId,
  mode: doc.mode,
  document: {
    content: doc.documentMarkdown,
    wordCount: doc.wordCount,
    format: 'markdown',
    generatedAt: doc.timestamp
  },
  message: `✅ Draf skripsi berhasil dibuat (${doc.wordCount} kata, mode: ${doc.mode})`,
  nextSteps: [
    'Gunakan action: validate_citations untuk verifikasi keaslian sitasi',
    'Ekspor dokumen ke PDF/DOCX via Gotenberg',
    'Lanjutkan ke bab berikutnya menggunakan session yang sama'
  ],
  meta: { model: 'gemma2:9b (open-weight)', engine: 'Ollama / Open-Source Agent Harness', poweredBy: 'AcademAI v2.0' }
};
